"""Duplicate / same-subject exclusions for HDA (generated by tools/make_dedup.py; details in outputs/dedup.json).

Found 2026-10-31 from FaceNet embeddings (Stage 4a): 15 groups of pair IDs hold re-saved copies of the same
photos (cosine >= 0.80; 320/333 byte-identical), 5 of them spanning dev and test. Rule: keep one pair per
duplicate group, and drop test pairs linked to a dev pair at cosine >= 0.70 (different-ID p99.99), so dev and
test share no subject. splits.json is unchanged; these IDs are excluded from every analysis.
"""
from __future__ import annotations

EXCLUDE = {
    "75": "test pair linked to dev pair 438 (cos 0.701 >= 0.7)",
    "84": "test pair linked to dev pair 120 (cos 0.749 >= 0.7)",
    "99": "duplicate of 150 (cos >= 0.8)",
    "101": "test pair linked to dev pair 59 (cos 0.714 >= 0.7)",
    "175": "duplicate of 134 (cos >= 0.8)",
    "188": "test pair linked to dev pair 227 (cos 0.715 >= 0.7)",
    "196": "test pair linked to dev pair 239 (cos 0.745 >= 0.7)",
    "226": "duplicate of 220 (cos >= 0.8)",
    "270": "duplicate of 129 (cos >= 0.8)",
    "281": "test pair linked to dev pair 259 (cos 0.722 >= 0.7)",
    "333": "duplicate of 320 (cos >= 0.8)",
    "352": "test pair linked to dev pair 227 (cos 0.766 >= 0.7)",
    "360": "duplicate of 597 (cos >= 0.8)",
    "392": "duplicate of 50 (cos >= 0.8)",
    "393": "duplicate of 377 (cos >= 0.8)",
    "483": "duplicate of 482 (cos >= 0.8)",
    "502": "test pair linked to dev pair 554 (cos 0.767 >= 0.7)",
    "530": "test pair linked to dev pair 503 (cos 0.746 >= 0.7)",
    "541": "duplicate of 366 (cos >= 0.8)",
    "558": "duplicate of 271 (cos >= 0.8)",
    "566": "duplicate of 358 (cos >= 0.8)",
    "602": "duplicate of 361 (cos >= 0.8)",
    "607": "duplicate of 362 (cos >= 0.8)",
    "630": "test pair linked to dev pair 376 (cos 0.740 >= 0.7)",
    "638": "duplicate of 511 (cos >= 0.8)",
}


def included(pids, split: dict[str, list[str]] | None = None, which: str | None = None) -> list[str]:
    """Pair IDs not excluded; optionally restricted to split[which] ('dev' or 'test')."""
    keep = set(split[which]) if (split is not None and which) else None
    return [p for p in pids if p not in EXCLUDE and (keep is None or p in keep)]
